//! Exact identifier-prefix fixtures generated by the pinned TypeScript reference.

use std::error::Error;

use keri_protocol::prefix::{IdentifierPrefix, PrefixDerivation, PrefixError, PrefixVerification};
use keri_protocol::said::DUMMY_CHARACTER;
use keri_protocol::serialization::{Sad, SadValue, SerializedEvent};
use serde::Deserialize;

const REFERENCE_SHA: &str = "ae92eceb8e776ad57669707bff7f84db9390b711";

#[derive(Debug, Deserialize)]
struct Fixture {
    schema_version: u8,
    upstream: String,
    reference_sha: String,
    generated_on: String,
    sources: Vec<String>,
    dummy_character: String,
    supported_codes: Vec<String>,
    incepting_ilks: Vec<String>,
    cases: Vec<PrefixCase>,
    completed_events: Vec<CompletedEvent>,
    parsed_prefixes: Vec<ParsedPrefix>,
    rejected_cases: Vec<RejectedCase>,
    reference_quirks: ReferenceQuirks,
}

#[derive(Debug, Deserialize)]
struct PrefixCase {
    name: String,
    derivation_code: String,
    input_sad_json: String,
    prefix: String,
    prefix_code: String,
    transferable: bool,
    digestive: bool,
    dummied_sad_json: Option<String>,
    placeholder: Option<String>,
    placeholder_width: Option<usize>,
    preimage: Option<String>,
    preimage_hex: Option<String>,
    preimage_byte_size: Option<usize>,
}

#[derive(Debug, Deserialize)]
struct CompletedEvent {
    name: String,
    derivation_code: String,
    completed_sad_json: String,
    reference_rederived_prefix: String,
    matches_original: bool,
}

#[derive(Debug, Deserialize)]
struct ParsedPrefix {
    qb64: String,
    code: String,
    transferable: bool,
    digestive: bool,
}

#[derive(Debug, Deserialize)]
struct RejectedCase {
    name: String,
    reference_error_category: String,
    reference_error_message: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct ReferenceQuirks {
    public_derive_and_verify_gate_on_the_identifier_field: GateQuirk,
    transferable_key_code_check_is_a_no_op: KeyCodeQuirk,
    non_transferable_verify_skips_backers_and_anchors: NonTransferableVerifyQuirk,
    verify_mutates_the_callers_event: MutationQuirk,
    constructor_super_called_twice: RejectedCase,
}

#[derive(Debug, Deserialize)]
struct GateQuirk {
    reference_error_category: String,
    reference_error_message: String,
    verify_accepted_when_identifier_field_is_the_ilk: bool,
    verify_prefixed_when_identifier_field_is_the_ilk: bool,
    verify_prefixed_on_a_completed_event: String,
    note: String,
    rust_decision: String,
}

#[derive(Debug, Deserialize)]
struct KeyCodeQuirk {
    requested_code: String,
    key: String,
    reference_prefix: String,
    reference_prefix_code: String,
    reference_transferable: bool,
    note: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct NonTransferableVerifyQuirk {
    reference_verify_with_next_keys: bool,
    reference_verify_with_backers: bool,
    reference_verify_with_anchors: bool,
    note: String,
    rust_decision: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct MutationQuirk {
    result: bool,
    event_before_json: String,
    event_after_json: String,
    note: String,
    rust_decision: String,
}

fn fixture() -> Result<Fixture, Box<dyn Error>> {
    Ok(serde_json::from_str(include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/fixtures/keri-prefix/v1.json"
    )))?)
}

fn decode_hex(input: &str) -> Result<Vec<u8>, Box<dyn Error>> {
    if !input.len().is_multiple_of(2) {
        return Err("odd-length hexadecimal fixture field".into());
    }
    (0..input.len())
        .step_by(2)
        .map(|index| {
            input
                .get(index..index + 2)
                .ok_or_else(|| Box::<dyn Error>::from("hexadecimal fixture slice out of range"))
                .and_then(|pair| u8::from_str_radix(pair, 16).map_err(Into::into))
        })
        .collect()
}

fn derivation_for(code: &str) -> Result<PrefixDerivation, Box<dyn Error>> {
    PrefixDerivation::ALL
        .into_iter()
        .find(|derivation| derivation.code().as_str() == code)
        .ok_or_else(|| format!("fixture names unsupported derivation code {code}").into())
}

/// Rebuilds `sad` with one field replaced or appended, preserving the original field order.
///
/// The crate keeps in-place replacement internal, so tests reconstruct through the public
/// insertion API rather than widening that surface.
fn with_field(sad: &Sad, label: &str, value: SadValue) -> Result<Sad, Box<dyn Error>> {
    let mut rebuilt = Sad::new();
    let mut replaced = false;
    for (existing, existing_value) in sad.entries() {
        if existing == label {
            rebuilt.insert(existing.to_owned(), value.clone())?;
            replaced = true;
        } else {
            rebuilt.insert(existing.to_owned(), existing_value.clone())?;
        }
    }
    if !replaced {
        rebuilt.insert(label.to_owned(), value)?;
    }
    Ok(rebuilt)
}

fn without_field(sad: &Sad, label: &str) -> Result<Sad, Box<dyn Error>> {
    let mut rebuilt = Sad::new();
    for (existing, existing_value) in sad.entries() {
        if existing != label {
            rebuilt.insert(existing.to_owned(), existing_value.clone())?;
        }
    }
    Ok(rebuilt)
}

fn prefix_error_category(error: &PrefixError) -> &'static str {
    match error {
        PrefixError::UnsupportedCode { .. } => "UnsupportedCode",
        PrefixError::MissingKeysField => "MissingKeysField",
        PrefixError::InvalidKeysField => "InvalidKeysField",
        PrefixError::KeyCount { .. } => "KeyCount",
        PrefixError::KeyCodeMismatch { .. } => "KeyCodeMismatch",
        PrefixError::NonTransferableFieldNotEmpty { .. } => "NonTransferableFieldNotEmpty",
        PrefixError::MissingEventKind => "MissingEventKind",
        PrefixError::NonInceptingEventKind { .. } => "NonInceptingEventKind",
        PrefixError::PrefixMismatch => "PrefixMismatch",
        PrefixError::MissingIdentifierField => "MissingIdentifierField",
        PrefixError::IdentifierFieldMismatch => "IdentifierFieldMismatch",
        PrefixError::EventKind { .. } => "EventKind",
        PrefixError::Sad { .. } => "Sad",
        PrefixError::Serialization { .. } => "Serialization",
        PrefixError::Crypto { .. } => "Crypto",
        PrefixError::Cesr { .. } => "Cesr",
        _ => "Unknown",
    }
}

#[test]
fn fixture_metadata_matches_the_pinned_reference() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.schema_version, 1);
    assert_eq!(fixture.upstream, "https://github.com/WebOfTrust/signify-ts.git");
    assert_eq!(fixture.reference_sha, REFERENCE_SHA);
    assert_ne!(fixture.generated_on, "");
    assert_eq!(
        fixture.sources,
        [
            "src/keri/core/prefixer.ts",
            "test/core/prefixer.test.ts",
            "test/core/serder.test.ts"
        ]
    );
    assert_eq!(fixture.dummy_character, DUMMY_CHARACTER.to_string());

    // The Rust derivation table must name exactly the codes the reference supports.
    let rust_codes: Vec<&str> = PrefixDerivation::ALL
        .into_iter()
        .map(|derivation| derivation.code().as_str())
        .collect();
    assert_eq!(rust_codes, fixture.supported_codes);
    assert_eq!(fixture.incepting_ilks, ["icp", "dip", "vcp"]);
    Ok(())
}

#[test]
fn every_reference_prefix_derives_exactly() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.cases.len(), 8);

    for case in &fixture.cases {
        let derivation = derivation_for(&case.derivation_code)?;
        let sad = Sad::from_json_bytes(case.input_sad_json.as_bytes())?;
        let prefix = IdentifierPrefix::derive(&sad, derivation)?;

        assert_eq!(prefix.qb64()?, case.prefix, "case {}", case.name);
        assert_eq!(prefix.code().as_str(), case.prefix_code, "case {}", case.name);
        assert_eq!(prefix.is_transferable(), case.transferable, "case {}", case.name);
        assert_eq!(prefix.is_digestive(), case.digestive, "case {}", case.name);
        assert_eq!(prefix.derivation(), derivation, "case {}", case.name);

        // A derived prefix round trips through its canonical text.
        assert_eq!(IdentifierPrefix::from_qb64(&case.prefix)?, prefix, "case {}", case.name);

        // Deriving again is a fixed point: the prefix does not depend on the caller's data being
        // untouched, which is the invariant the reference breaks by mutating it.
        assert_eq!(
            IdentifierPrefix::derive(&sad, derivation)?,
            prefix,
            "case {}",
            case.name
        );
    }
    Ok(())
}

#[test]
fn the_hashed_preimage_matches_byte_for_byte() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let mut checked = 0_usize;

    for case in &fixture.cases {
        let (Some(preimage), Some(preimage_hex), Some(size), Some(placeholder), Some(width), Some(dummied_json)) = (
            case.preimage.as_ref(),
            case.preimage_hex.as_ref(),
            case.preimage_byte_size,
            case.placeholder.as_ref(),
            case.placeholder_width,
            case.dummied_sad_json.as_ref(),
        ) else {
            // Basic derivations hash nothing.
            assert!(
                matches!(case.derivation_code.as_str(), "B" | "D"),
                "case {} has no preimage but is not a basic derivation",
                case.name
            );
            continue;
        };

        // The placeholder is exactly as wide as the prefix that replaces it, which is what keeps
        // the version-string size correct for the finished event.
        assert_eq!(width, case.prefix.len(), "case {}", case.name);
        assert!(
            placeholder.chars().all(|character| character == DUMMY_CHARACTER),
            "case {} placeholder is not all dummy characters",
            case.name
        );

        let expected = decode_hex(preimage_hex)?;
        assert_eq!(
            expected,
            preimage.as_bytes(),
            "case {} preimage hex/text disagree",
            case.name
        );
        assert_eq!(expected.len(), size, "case {}", case.name);

        // Rebuild the placeholder-bearing intermediate exactly as derivation does, then confirm it
        // equals the bytes the reference hashed. This isolates the placeholder-and-size step from
        // BLAKE3, so a mismatch points at serialization rather than at the digest.
        let sad = Sad::from_json_bytes(case.input_sad_json.as_bytes())?;
        let dummy: String = core::iter::repeat_n(DUMMY_CHARACTER, width).collect();
        let mut dummied = sad;
        for label in ["i", "d"] {
            dummied = with_field(&dummied, label, SadValue::text(dummy.clone()))?;
        }
        let event = SerializedEvent::from_sad(dummied)?;
        assert_eq!(event.raw(), preimage.as_bytes(), "case {}", case.name);
        assert_eq!(
            event.sad(),
            &Sad::from_json_bytes(dummied_json.as_bytes())?,
            "case {}",
            case.name
        );
        checked += 1;
    }
    assert_eq!(checked, 5, "every self-addressing case must pin a preimage");
    Ok(())
}

#[test]
fn the_reference_accepts_the_events_rust_completes() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.completed_events.len(), fixture.cases.len());

    for (case, completed) in fixture.cases.iter().zip(&fixture.completed_events) {
        assert_eq!(case.name, completed.name);
        assert_eq!(case.derivation_code, completed.derivation_code);

        let derivation = derivation_for(&case.derivation_code)?;
        let sad = Sad::from_json_bytes(case.input_sad_json.as_bytes())?;
        let prefix = IdentifierPrefix::derive(&sad, derivation)?;

        // Fill the identifier field -- and, for a digestive prefix, the SAID field -- exactly as
        // an event builder will.
        let mut rust_completed = with_field(&sad, "i", SadValue::text(prefix.qb64()?))?;
        if prefix.is_digestive() {
            rust_completed = with_field(&rust_completed, "d", SadValue::text(prefix.qb64()?))?;
        }

        // Those exact bytes are what the fixture handed back to the pinned reference, which
        // re-derived the same prefix from them. Byte equality here is what makes the recorded
        // reference acceptance a statement about the Rust artifact.
        assert_eq!(
            rust_completed.to_json_bytes()?,
            completed.completed_sad_json.as_bytes(),
            "case {} completed bytes differ from the ones the reference accepted",
            case.name
        );
        assert!(completed.matches_original, "case {}", case.name);
        assert_eq!(completed.reference_rederived_prefix, case.prefix, "case {}", case.name);
        assert_eq!(
            prefix.qb64()?,
            completed.reference_rederived_prefix,
            "case {}",
            case.name
        );
    }
    Ok(())
}

#[test]
fn parsed_prefix_metadata_matches() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.parsed_prefixes.len(), 3);
    for parsed in &fixture.parsed_prefixes {
        let prefix = IdentifierPrefix::from_qb64(&parsed.qb64)?;
        assert_eq!(prefix.code().as_str(), parsed.code, "prefix {}", parsed.qb64);
        assert_eq!(prefix.is_transferable(), parsed.transferable, "prefix {}", parsed.qb64);
        assert_eq!(prefix.is_digestive(), parsed.digestive, "prefix {}", parsed.qb64);
        assert_eq!(prefix.to_string(), parsed.qb64);
    }
    Ok(())
}

#[test]
fn a_completed_event_verifies_strictly() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    for case in &fixture.cases {
        let derivation = derivation_for(&case.derivation_code)?;
        let sad = Sad::from_json_bytes(case.input_sad_json.as_bytes())?;
        let prefix = IdentifierPrefix::derive(&sad, derivation)?;

        // Fill in the identifier field the way an event builder will, and, for a self-addressing
        // prefix, the SAID field it also commits to. Substituting the prefix for the placeholder
        // cannot change any byte count, so the derivation is unchanged.
        let mut completed = with_field(&sad, "i", SadValue::text(prefix.qb64()?))?;
        if prefix.is_digestive() {
            completed = with_field(&completed, "d", SadValue::text(prefix.qb64()?))?;
        }
        prefix.verify(&completed, PrefixVerification::Strict)?;
        prefix.verify(&completed, PrefixVerification::DerivationOnly)?;
        assert_eq!(
            IdentifierPrefix::derive(&completed, derivation)?,
            prefix,
            "case {} changed under completion",
            case.name
        );

        // An event claiming a different prefix is rejected by the strict policy.
        let impostor = with_field(
            &completed,
            "i",
            SadValue::text("EBabiu_JCkE0GbiglDXNB5C4NQq-hiGgxhHKXBxkiojg"),
        )?;
        let error = prefix
            .verify(&impostor, PrefixVerification::Strict)
            .err()
            .ok_or("strict verification accepted an unrelated identifier field")?;
        assert!(
            matches!(
                error,
                PrefixError::IdentifierFieldMismatch | PrefixError::PrefixMismatch
            ),
            "case {} produced {error:?}",
            case.name
        );
    }
    Ok(())
}

#[test]
fn reference_rejections_map_to_stable_rust_error_categories() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.rejected_cases.len(), 14);

    let pinned = fixture
        .cases
        .first()
        .ok_or("fixture has no cases")?
        .input_sad_json
        .clone();
    let pinned = Sad::from_json_bytes(pinned.as_bytes())?;
    let serder = fixture
        .cases
        .get(2)
        .ok_or("fixture has no serder case")?
        .input_sad_json
        .clone();
    let serder = Sad::from_json_bytes(serder.as_bytes())?;
    let non_transferable = fixture
        .cases
        .get(4)
        .ok_or("fixture has no non-transferable case")?
        .input_sad_json
        .clone();
    let non_transferable = Sad::from_json_bytes(non_transferable.as_bytes())?;

    let key = |qb64: &str| SadValue::Array(vec![SadValue::text(qb64)]);
    let transferable_key = "DKxy2sgzfplyr-tgwIxS19f2OchFHtLwPWD3v4oYimBx";
    let next_digest = "EAKUR-LmLHWMwXTLWQ1QjxHrihBmwwrV2tYaSG7hOrWj";

    for case in &fixture.rejected_cases {
        assert!(!case.reference_error_category.is_empty(), "case {}", case.name);
        assert!(!case.reference_error_message.is_empty(), "case {}", case.name);

        let error = match case.name.as_str() {
            "two_keys" => IdentifierPrefix::derive(
                &with_field(
                    &pinned,
                    "k",
                    SadValue::Array(vec![SadValue::text(transferable_key), SadValue::text(transferable_key)]),
                )?,
                PrefixDerivation::Ed25519,
            ),
            "zero_keys" => IdentifierPrefix::derive(
                &with_field(&pinned, "k", SadValue::Array(Vec::new()))?,
                PrefixDerivation::Ed25519,
            ),
            "missing_keys_field" => IdentifierPrefix::derive(&without_field(&pinned, "k")?, PrefixDerivation::Ed25519),
            "malformed_key" => {
                IdentifierPrefix::derive(&with_field(&pinned, "k", key("not-a-key"))?, PrefixDerivation::Ed25519)
            }
            "non_transferable_derivation_with_transferable_key" => {
                IdentifierPrefix::derive(&pinned, PrefixDerivation::Ed25519NonTransferable)
            }
            "non_transferable_with_next_keys" => IdentifierPrefix::derive(
                &with_field(&non_transferable, "n", key(next_digest))?,
                PrefixDerivation::Ed25519NonTransferable,
            ),
            "non_transferable_with_backers" => IdentifierPrefix::derive(
                &with_field(&non_transferable, "b", key(transferable_key))?,
                PrefixDerivation::Ed25519NonTransferable,
            ),
            "non_transferable_with_anchors" => IdentifierPrefix::derive(
                &with_field(&non_transferable, "a", SadValue::Array(vec![SadValue::text("x")]))?,
                PrefixDerivation::Ed25519NonTransferable,
            ),
            "non_incepting_event_kind" => IdentifierPrefix::derive(
                &with_field(&serder, "t", SadValue::text("rot"))?,
                PrefixDerivation::Blake3_256,
            ),
            "missing_event_kind" => {
                IdentifierPrefix::derive(&without_field(&serder, "t")?, PrefixDerivation::Blake3_256)
            }
            "missing_version_string" => {
                IdentifierPrefix::derive(&without_field(&serder, "v")?, PrefixDerivation::Blake3_256)
            }
            "unsupported_derivation_code" => {
                // A digest code the reference rejects only after deriving cannot be requested at
                // all: `PrefixDerivation` names exactly the three supported derivations.
                assert_eq!(case.rust_error_category, "UnsupportedCode");
                assert!(case.reference_error_message.contains("Unsupported code = H"));
                continue;
            }
            "p256_key_cannot_form_a_prefix" => IdentifierPrefix::derive(
                &with_field(&serder, "k", key("1AAJA-blKBTkTkEEOX_Yq3i3KxZJvcHarPfu_crKVwcfEwvQ"))?,
                PrefixDerivation::Ed25519,
            ),
            "non_prefix_qualified_material" => {
                IdentifierPrefix::from_qb64("HLEjyRTtmfyp4VpTBTkv_b6KONMS1V8-EW-aGJ5P_QMo")
            }
            other => return Err(format!("unmapped rejected case {other}").into()),
        }
        .err()
        .ok_or_else(|| format!("Rust accepted rejected case {}", case.name))?;

        assert_eq!(
            prefix_error_category(&error),
            case.rust_error_category,
            "case {}",
            case.name
        );
    }
    Ok(())
}

#[test]
fn reference_quirks_are_pinned_and_safely_diverged() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let quirks = &fixture.reference_quirks;
    let pinned = Sad::from_json_bytes(
        fixture
            .cases
            .first()
            .ok_or("fixture has no cases")?
            .input_sad_json
            .as_bytes(),
    )?;
    let non_transferable = Sad::from_json_bytes(
        fixture
            .cases
            .get(4)
            .ok_or("fixture has no non-transferable case")?
            .input_sad_json
            .as_bytes(),
    )?;

    // 1. The public derive/verify gate compares the identifier field against the `icp` ilk, so
    //    every real event throws and `prefixed=true` can never pass.
    let gate = &quirks.public_derive_and_verify_gate_on_the_identifier_field;
    assert_eq!(gate.reference_error_category, "Error");
    assert!(gate.reference_error_message.contains("Non-incepting ilk"));
    assert!(gate.verify_accepted_when_identifier_field_is_the_ilk);
    assert!(
        !gate.verify_prefixed_when_identifier_field_is_the_ilk,
        "the reference's prefixed check cannot succeed: reaching it requires i == \"icp\""
    );
    assert!(
        gate.verify_prefixed_on_a_completed_event.contains("Non-incepting ilk"),
        "an event that does claim its prefix cannot even reach the prefixed check"
    );
    assert_ne!(gate.note, "");
    assert_ne!(gate.rust_decision, "");

    // Rust performs the check the reference intends, on a real event.
    let prefix = IdentifierPrefix::derive(&pinned, PrefixDerivation::Blake3_256)?;
    let completed = with_field(
        &with_field(&pinned, "i", SadValue::text(prefix.qb64()?))?,
        "d",
        SadValue::text(prefix.qb64()?),
    )?;
    prefix.verify(&completed, PrefixVerification::Strict)?;

    // 2. The transferable key-code check is a no-op, so a `B` key yields a `B` prefix.
    let swap = &quirks.transferable_key_code_check_is_a_no_op;
    assert_eq!(swap.requested_code, "D");
    assert_eq!(swap.reference_prefix, swap.key);
    assert_eq!(swap.reference_prefix_code, "B");
    assert!(
        !swap.reference_transferable,
        "a caller who asked for a rotatable identifier received one that can never rotate"
    );
    assert_ne!(swap.note, "");
    let error = IdentifierPrefix::derive(&non_transferable, PrefixDerivation::Ed25519)
        .err()
        .ok_or("the transferable derivation accepted a non-transferable key")?;
    assert_eq!(prefix_error_category(&error), swap.rust_error_category);

    // 3. Non-transferable verification skips backers and anchors.
    let skipped = &quirks.non_transferable_verify_skips_backers_and_anchors;
    assert!(!skipped.reference_verify_with_next_keys);
    assert!(skipped.reference_verify_with_backers);
    assert!(skipped.reference_verify_with_anchors);
    assert_ne!(skipped.note, "");
    assert_ne!(skipped.rust_decision, "");

    let non_transferable_prefix =
        IdentifierPrefix::derive(&non_transferable, PrefixDerivation::Ed25519NonTransferable)?;
    for label in ["b", "a"] {
        let populated = with_field(
            &non_transferable,
            label,
            SadValue::Array(vec![SadValue::text("DKxy2sgzfplyr-tgwIxS19f2OchFHtLwPWD3v4oYimBx")]),
        )?;
        let error = non_transferable_prefix
            .verify(&populated, PrefixVerification::DerivationOnly)
            .err()
            .ok_or("verification accepted content the derivation rejects")?;
        assert_eq!(prefix_error_category(&error), skipped.rust_error_category);
    }

    // 4. Verification mutates the caller's event.
    let mutation = &quirks.verify_mutates_the_callers_event;
    assert!(mutation.result);
    assert_ne!(
        mutation.event_before_json, mutation.event_after_json,
        "the reference must be shown to modify the event it verified"
    );
    assert!(mutation.event_after_json.contains(DUMMY_CHARACTER));
    assert!(!mutation.event_before_json.contains(DUMMY_CHARACTER));
    assert_ne!(mutation.note, "");
    assert_ne!(mutation.rust_decision, "");

    let before = completed.clone();
    prefix.verify(&completed, PrefixVerification::Strict)?;
    assert_eq!(completed, before, "Rust verification must not disturb the event");

    // The same fixture also shows the reference accepting an event whose identifier field is the
    // literal `icp` rather than the prefix; Rust's default policy rejects that.
    let mislabeled = Sad::from_json_bytes(mutation.event_before_json.as_bytes())?;
    assert!(matches!(
        prefix.verify(&mislabeled, PrefixVerification::Strict),
        Err(PrefixError::IdentifierFieldMismatch)
    ));
    prefix.verify(&mislabeled, PrefixVerification::DerivationOnly)?;

    // 5. The constructor calls super() twice when the identifier field is populated.
    let constructor = &quirks.constructor_super_called_twice;
    assert_eq!(constructor.reference_error_category, "ReferenceError");
    assert!(constructor.reference_error_message.contains("Super constructor"));
    assert_eq!(constructor.rust_error_category, "UnreachableInRust");
    // Rust reaches the same goal without a constructor overload: parse the claimed prefix and
    // verify against it.
    let claimed = completed.get_text("i").ok_or("completed event lacks its identifier")?;
    IdentifierPrefix::from_qb64(claimed)?.verify(&completed, PrefixVerification::Strict)?;
    Ok(())
}
